    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "किं तूद्भ्रान्तपतत्पतङ्गपवनव्यालोलदीपाङ्कुर-",
          "end": "line"
        },
        {
          "n": 2,
          "text": "च्छायाचञ्चलमाकलय्य सकलं सन्तो वनान्तं गताः ॥ ६८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "किं कन्दाः कन्दरेभ्यः प्रलयमुपगता निर्झरा वा गिरिभ्यः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "प्रध्वस्ता वा तरुभ्यः सरसफलभृतो वल्कलिन्यश्च शाखाः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "वीक्ष्यन्ते यन्मुखानि प्रसभमपगतप्रश्रयाणां खलानां",
          "end": "line"
        },
        {
          "n": 4,
          "text": "दुःखोपात्ताल्पवित्तस्मयवशपवनानर्तितभ्रूलतानि ॥ ६९ ॥",
          "end": "space"
        },
        {
          "n": 5,
          "text": "",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "गङ्गातरङ्गकणशीकरशीतलानि",
          "end": "line"
        },
        {
          "n": 2,
          "text": "विद्याधराध्युषितचारुशिलातलानि ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "स्थानानि किं हिमवतः प्रलयं गतानि",
          "end": "line"
        },
        {
          "n": 4,
          "text": "यत्सावमानपरपिण्डरता मनुष्याः ॥ ७० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "यदा मेरुः श्रीमान्निपतति युगान्ताग्निनिहतः",
          "end": "line"
        },
        {
          "n": 2,
          "text": "समुद्राः शुष्यन्ति प्रचुरनिकरग्राहनिलयाः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "धरा गच्छत्यन्तं धरणिधरपादैरपि धृता",
          "end": "line"
        },
        {
          "n": 4,
          "text": "शरीरे का वार्त्ता करिकलभकर्णाग्रचपले ॥ ७१ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
